sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.script:
(function() {
    /* populate the 'data' object */
    /* e.g., data.table = $sp.getValue('table'); */
    var cogGR = new GlideRecord('x_476139_ebay_sourcing_trip');
    cogGR.addEncodedQuery('dateONThis year@javascript:gs.beginningOfThisYear()@javascript:gs.endOfThisYear()');
    cogGR.query();
    var totalAmount = 0;
    var totalItems = 0;

    while (cogGR.next()) {
        var amount = parseFloat(cogGR.getValue('amount'));
        var items = parseInt(cogGR.getValue('number_of_items'), 10);
        totalAmount += amount;
        totalItems += items;
    }
    console.log('total amount: ' + totalAmount);
    console.log('total Items: ' + totalItems);

    var average = (totalAmount / totalItems).toFixed(2);
    data.average = average;

	var totalSales = 0;
	var totalFees = 0;
	var totalPromotedListingFees = 0;
	var totalShippingFees = 0;
    var itemGR = new GlideRecord('x_476139_ebay_item');
    itemGR.addEncodedQuery('sale_dateONThis year@javascript:gs.beginningOfThisYear()@javascript:gs.endOfThisYear()');
	itemGR.query();
	var soldItems = itemGR.getRowCount();
	while(itemGR.next()){
		var salePrice = parseFloat(itemGR.getValue('selling_price'), 10);
		var fees = parseFloat(itemGR.getValue('fees'), 10);
		var promotedListingFees = parseFloat(itemGR.getValue('promoted_listing_fee'), 10);
		var shippingFees = parseFloat(itemGR.getValue('shipping'), 10);
		totalSales += salePrice;
		totalFees += fees;
		totalPromotedListingFees += promotedListingFees;
		totalShippingFees += shippingFees;
	}
	console.log('totalSales: ' + totalSales);
	console.log('average: ' + parseFloat(average))
	console.log('totalFees: ' + totalFees);
	console.log('totalPromotedListingFees: ' + totalPromotedListingFees);
	console.log('totalShippingFees: ' + totalShippingFees);
	var totalExpenses = totalFees + totalPromotedListingFees + totalShippingFees + ((parseFloat(average)) * soldItems);
	console.log('totalExpenses: ' + totalExpenses);
	var totalProfit = parseFloat(totalSales - totalExpenses, 10);
	data.totalProfit = totalProfit.toFixed(2);
	//console.log('totalExpenses: ' + totalExpenses);
	console.log('totalProfit: ' + totalProfit);
	var averageProfit = (totalProfit / soldItems).toFixed(2);
	console.log('soldItems: ' + soldItems);
	data.averageProfit = averageProfit;

	var expenseGR = new GlideRecord('x_476139_ebay_expense');
	expenseGR.addEncodedQuery('company=cedar_river_vintage^dateONThis year@javascript:gs.beginningOfThisYear()@javascript:gs.endOfThisYear()');
	expenseGR.query();
	var expenseTotal = 0;
	while(expenseGR.next()){
		expenseTotal += parseFloat(expenseGR.getValue('price'));
	}
	data.totalExpenses = expenseTotal.toFixed(2);

})();
